import { useState } from "react";

function Hero({ onSearch, loading }) {
  const [city, setCity] = useState("");

  function submit(event) {
    event.preventDefault();
    if (!city.trim()) return;

    onSearch(city);
    setCity("");
  }

  const today = new Intl.DateTimeFormat("uk-UA", {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
  }).format(new Date());

  return (
    <section className="hero" id="home">
      <div className="hero-content">
        <span className="eyebrow">ТВОЯ ПОГОДА — ЗАВЖДИ ПОРУЧ</span>
        <h1>Відчуй погоду.</h1>
        <p>
          Прогноз, який допомагає планувати кожен день.
          Перевір погоду у своєму місті.
        </p>

        <form className="search-form" onSubmit={submit}>
          <span>⌕</span>
          <input
            value={city}
            onChange={(event) => setCity(event.target.value)}
            placeholder="Введи назву міста..."
            aria-label="Назва міста"
          />
          <button className="primary-button" disabled={loading}>
            {loading ? "Пошук..." : "Знайти"}
          </button>
        </form>

        <div className="hero-date">
          <span>◷</span> {today}
        </div>
      </div>

      <div className="hero-art" aria-hidden="true">
        <div className="sun">☀</div>
        <div className="cloud cloud-one">☁</div>
        <div className="cloud cloud-two">☁</div>
        <div className="hero-temperature">24°</div>
      </div>
    </section>
  );
}

export default Hero;
